package main

import (
	"bufio"
	"os"
	"sort"
)

func main() {
	scanner := NewFastScanner(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	n := scanner.NextInt()
	m := scanner.NextInt()

	type container struct {
		a, b int
	}
	containers := make([]container, m)
	for i := 0; i < m; i++ {
		containers[i].a = scanner.NextInt()
		containers[i].b = scanner.NextInt()
	}

	sort.Slice(containers, func(i, j int) bool {
		return containers[i].b < containers[j].b
	})

	sum := 0
	for i := m - 1; i >= 0; i-- {
		if containers[i].a < n {
			sum += containers[i].a * containers[i].b
			n -= containers[i].a
		} else {
			sum += n * containers[i].b
			break
		}
	}

	writer.WriteString(strconv.Itoa(sum))
	writer.WriteByte('\n')
}

type FastScanner struct {
	reader *bufio.Reader
	buf    []byte
}

func NewFastScanner(r *os.File) *FastScanner {
	return &FastScanner{
		reader: bufio.NewReader(r),
		buf:    make([]byte, 0, 1024*10),
	}
}

func (s *FastScanner) NextInt() int {
	s.buf = s.buf[:0]
	c, _ := s.reader.ReadByte()
	for c < '0' || c > '9' {
		c, _ = s.reader.ReadByte()
	}
	s.buf = append(s.buf, c)
	for {
		c, err := s.reader.ReadByte()
		if err != nil || c < '0' || c > '9' {
			break
		}
		s.buf = append(s.buf, c)
	}
	val := 0
	for _, ch := range s.buf {
		val = val*10 + int(ch-'0')
	}
	return val
}

